CREATE TABLE repositories (id text PRIMARY KEY, name text NOT NULL UNIQUE, criticality text NOT NULL CHECK (criticality IN ('normal','high','safety')));
CREATE TABLE pull_requests (id text PRIMARY KEY, repository_id text NOT NULL REFERENCES repositories(id), number integer NOT NULL CHECK (number > 0), title text NOT NULL, description text NOT NULL, author text NOT NULL, revision text NOT NULL, evidence jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(repository_id, number));
CREATE TABLE policy_versions (id text PRIMARY KEY, version integer NOT NULL UNIQUE CHECK (version > 0), policy jsonb NOT NULL, author text NOT NULL, published_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE risk_assessments (id text PRIMARY KEY, pull_request_id text NOT NULL REFERENCES pull_requests(id), policy_version_id text NOT NULL REFERENCES policy_versions(id), provider text NOT NULL CHECK(provider IN ('demo','openrouter')), model text NOT NULL, requested_model text NOT NULL, status text NOT NULL CHECK(status IN ('completed','failed')), state_hash text NOT NULL, aggregate_risk real CHECK(aggregate_risk BETWEEN 0 AND 10), error_code text, created_at timestamptz NOT NULL DEFAULT now(), sequence integer GENERATED ALWAYS AS IDENTITY, CHECK ((status = 'completed' AND error_code IS NULL AND aggregate_risk IS NOT NULL) OR (status = 'failed' AND error_code IS NOT NULL AND aggregate_risk IS NULL)));
CREATE UNIQUE INDEX completed_assessment_revision ON risk_assessments(pull_request_id, policy_version_id, provider, requested_model, state_hash) WHERE status = 'completed';
CREATE FUNCTION valid_probabilities(values_json jsonb) RETURNS boolean LANGUAGE sql IMMUTABLE AS $$ SELECT jsonb_typeof(values_json) = 'array' AND jsonb_array_length(values_json) = 5 AND (SELECT bool_and(v::text::numeric BETWEEN 0 AND 1) AND abs(sum(v::text::numeric) - 1) < 0.001 FROM jsonb_array_elements(values_json) AS v) $$;
CREATE TABLE dimension_scores (assessment_id text NOT NULL REFERENCES risk_assessments(id), dimension text NOT NULL CHECK(dimension IN ('scope','criticality','testing','rollback','security')), score real NOT NULL CHECK(score BETWEEN 0 AND 10), confidence real NOT NULL CHECK(confidence BETWEEN 0 AND 1), criteria jsonb NOT NULL CHECK(jsonb_array_length(criteria)=5), probabilities jsonb NOT NULL CHECK(valid_probabilities(probabilities)), UNIQUE(assessment_id, dimension));
CREATE TABLE routing_decisions (id text PRIMARY KEY, pull_request_id text NOT NULL REFERENCES pull_requests(id), assessment_id text NOT NULL REFERENCES risk_assessments(id), policy_version_id text NOT NULL REFERENCES policy_versions(id), route text NOT NULL CHECK(route IN ('fast','standard','critical','triage')), result jsonb NOT NULL, kind text NOT NULL CHECK(kind IN ('assessment','override')), actor text NOT NULL, override_reason text, created_at timestamptz NOT NULL DEFAULT now(), sequence integer GENERATED ALWAYS AS IDENTITY, CHECK(kind != 'override' OR length(trim(override_reason)) > 0));
CREATE INDEX decisions_by_pr ON routing_decisions(pull_request_id, sequence DESC);
CREATE TABLE reviewers (id text PRIMARY KEY, name text NOT NULL, username text NOT NULL UNIQUE, capacity integer NOT NULL CHECK(capacity > 0), available boolean NOT NULL);
CREATE TABLE reviewer_skills (reviewer_id text NOT NULL REFERENCES reviewers(id), skill text NOT NULL, UNIQUE(reviewer_id, skill));
CREATE TABLE review_assignments (id text PRIMARY KEY, pull_request_id text NOT NULL REFERENCES pull_requests(id), reviewer_id text NOT NULL REFERENCES reviewers(id), status text NOT NULL CHECK(status IN ('active','completed')), role text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX active_reviewer_assignment ON review_assignments(pull_request_id, reviewer_id) WHERE status = 'active';
CREATE TABLE audit_events (id text PRIMARY KEY, type text NOT NULL, actor text NOT NULL, pull_request_id text REFERENCES pull_requests(id), repository text, route text CHECK(route IN ('fast','standard','critical','triage')), details jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), sequence integer GENERATED ALWAYS AS IDENTITY);
CREATE INDEX audit_by_pr ON audit_events(pull_request_id, sequence DESC);
CREATE TABLE idempotency_keys (key text PRIMARY KEY, request_hash text NOT NULL, response jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION reject_history_change() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Historical records are immutable'; END; $$;
CREATE TRIGGER policy_immutable BEFORE UPDATE OR DELETE ON policy_versions FOR EACH ROW EXECUTE FUNCTION reject_history_change();
CREATE TRIGGER decision_immutable BEFORE UPDATE OR DELETE ON routing_decisions FOR EACH ROW EXECUTE FUNCTION reject_history_change();
CREATE TRIGGER assessment_immutable BEFORE UPDATE OR DELETE ON risk_assessments FOR EACH ROW EXECUTE FUNCTION reject_history_change();
CREATE TRIGGER scores_immutable BEFORE UPDATE OR DELETE ON dimension_scores FOR EACH ROW EXECUTE FUNCTION reject_history_change();
CREATE TRIGGER audit_immutable BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION reject_history_change();
